def compute_s(M):
    s1 = 0
    for n in range(1, M):
        term1 = M**n
        denom1 = 1
        for k in range(1, n + 1):
            denom1 *= (M + k)
        s1 += term1 / denom1

    s2 = 0
    for n in range(1, M):
        num2 = 1
        for k in range(1, n + 1):
            num2 *= (M - k)
        s2 += num2 / (M**n)

    return s1 - s2

for M in range(2, 11):
    print(f"M={M}, S={compute_s(M)}")

